<?php
require_once __DIR__.'/includes/functions.php';$slug=slugify($_GET['slug']??'');$eventId=(int)($_GET['event']??0);try{$q=db()->prepare('SELECT i.*,c.bride_name,c.groom_name FROM invitations i LEFT JOIN couples c ON c.invitation_id=i.id WHERE i.slug=? AND i.status="active" LIMIT 1');$q->execute([$slug]);$inv=$q->fetch();if(!$inv)throw new RuntimeException();$q=db()->prepare('SELECT * FROM events WHERE invitation_id=? AND status=1 '.($eventId?'AND id='.((int)$eventId):'').' ORDER BY sort_order,id LIMIT 1');$q->execute([$inv['id']]);$event=$q->fetch();if(!$event)throw new RuntimeException();$date=date('Ymd',strtotime($event['event_date']));$start=$date.'T080000';$end=$date.'T120000';header('Content-Type: text/calendar; charset=utf-8');header('Content-Disposition: attachment; filename="'.$slug.'.ics"');echo "BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//WAKTUTEMU.ID//Wedding//ID\r\nBEGIN:VEVENT\r\nUID:".bin2hex(random_bytes(8))."@waktutemu.id\r\nDTSTAMP:".gmdate('Ymd\THis\Z')."\r\nDTSTART:{$start}\r\nDTEND:{$end}\r\nSUMMARY:".str_replace(["\r","\n",','],['','','\\,'],$event['title'])." - ".str_replace(["\r","\n",','],['','','\\,'],$inv['bride_name'].' & '.$inv['groom_name'])."\r\nLOCATION:".str_replace(["\r","\n",','],['','','\\,'],$event['venue'].' '.$event['address'])."\r\nEND:VEVENT\r\nEND:VCALENDAR\r\n";}catch(Throwable){http_response_code(404);echo 'Event tidak ditemukan.';}
